def control(obs):
    global phase
    h = obs['hitch_deg']
    v = obs['motion']['v_mps']
    if phase == 'fwd':
        if h < 1.0:
            phase = 'stop'
        return (0.0, 0.5, -64)
    if phase == 'stop':
        if abs(v) < 0.05:
            phase = 'rev'
        return (0.0, 0.0, -64)
    steer = max(-45.0, min(45.0, 2.0 * (h - 2.0)))
    return (steer, -0.7, -64)

