import math
S={'rec':False}
def clamp(x,lo,hi):
    return max(lo,min(hi,x))
def control(obs):
    h=obs['hitch_deg']
    y=obs['rig']['trailer_rear'][1]
    if abs(h)>45 or obs['status']=='JACKKNIFED':
        S['rec']=True
    if S['rec'] and abs(h)<12:
        S['rec']=False
    if S['rec']:
        return (0.0,0.6)
    ht=clamp(-19*(y+0.25),-20,20)
    steer=clamp(4*(h-ht),-40,40)
    return (steer,-0.6)

